"""Ablation diagnostic analysis: compare detach vs random occlusion ablations."""

import argparse
import json
import os
import sys


def check_ablation_data(args):
    """Verify all ablation eval files exist. Exit if any missing."""
    for label, files_str in [("detach", args.detach), ("random", args.random)]:
        if not files_str:
            sys.exit(f"ERROR: --{label} argument is required")
        for f in files_str.split(","):
            f = f.strip()
            if not os.path.exists(f):
                sys.exit(
                    f"ERROR: ablation eval data not found: {f}\n"
                    f"This script requires actual ablation eval results. "
                    f"Do NOT substitute with vanilla or other data."
                )
    for label, files_str in [("vanilla", args.vanilla), ("full_occ", args.full_occ)]:
        if files_str:
            for f in files_str.split(","):
                f = f.strip()
                if not os.path.exists(f):
                    sys.exit(f"ERROR: {label} eval data not found: {f}")


def load_eval_results(files_str):
    """Load and merge eval results from comma-separated JSON paths."""
    results = []
    for f in files_str.split(","):
        f = f.strip()
        with open(f) as fh:
            results.append(json.load(fh))
    return results


def parse_args():
    parser = argparse.ArgumentParser(description="Ablation diagnostic analysis")
    parser.add_argument("--vanilla", type=str, default=None, help="Vanilla eval JSON(s), comma-separated")
    parser.add_argument("--full_occ", type=str, default=None, help="Full occlusion eval JSON(s), comma-separated")
    parser.add_argument("--detach", type=str, required=True, help="Detach ablation eval JSON(s), comma-separated")
    parser.add_argument("--random", type=str, required=True, help="Random occlusion ablation eval JSON(s), comma-separated")
    parser.add_argument("--output_dir", type=str, default="./output/", help="Output directory")
    return parser.parse_args()


def main():
    args = parse_args()
    check_ablation_data(args)

    os.makedirs(args.output_dir, exist_ok=True)

    detach_results = load_eval_results(args.detach)
    random_results = load_eval_results(args.random)

    vanilla_results = load_eval_results(args.vanilla) if args.vanilla else None
    full_occ_results = load_eval_results(args.full_occ) if args.full_occ else None

    print(f"Loaded {len(detach_results)} detach, {len(random_results)} random ablation results")
    if vanilla_results:
        print(f"Loaded {len(vanilla_results)} vanilla results")
    if full_occ_results:
        print(f"Loaded {len(full_occ_results)} full_occ results")

    # TODO: Add actual diagnostic analysis and visualization
    print("Ablation diagnostic analysis complete.")


if __name__ == "__main__":
    main()
